package com.royalcoffee.pos.printer

import com.royalcoffee.pos.model.PrinterConfig
import com.royalcoffee.pos.model.Receipt
import com.royalcoffee.pos.model.ReceiptItem
import java.io.ByteArrayOutputStream
import java.nio.charset.Charset

/**
 * EscPosReceiptFormatter converts a Receipt object into a thermal-printer-friendly format.
 *
 * Important:
 * This class does not connect to a printer.
 * It only prepares the receipt content.
 *
 * Later, BluetoothReceiptPrinter will use this formatter and send the generated bytes
 * to a real ESC/POS thermal printer.
 */
class EscPosReceiptFormatter {

    /**
     * Converts a Receipt object into plain receipt text.
     *
     * This text is useful for:
     * - Debugging
     * - Thermal receipt preview
     * - Preparing ESC/POS byte output
     *
     * The line width comes from PrinterConfig.
     *
     * Example:
     * 58mm printer usually uses around 32 characters per line.
     */
    fun formatReceiptText(
        receipt: Receipt,
        printerConfig: PrinterConfig
    ): String {
        val lineWidth = printerConfig.charactersPerLine.coerceIn(
            minimumValue = 24,
            maximumValue = 48
        )

        val builder = StringBuilder()

        appendCenteredLine(
            builder = builder,
            text = receipt.storeName.uppercase(),
            lineWidth = lineWidth
        )

        receipt.storeAddressLines.forEach { addressLine ->
            appendCenteredLine(
                builder = builder,
                text = addressLine,
                lineWidth = lineWidth
            )
        }

        appendCenteredLine(
            builder = builder,
            text = "Tel: ${receipt.storePhone}",
            lineWidth = lineWidth
        )

        appendBlankLine(builder)
        appendDivider(builder, lineWidth)

        appendLeftRightLine(
            builder = builder,
            left = "Receipt:",
            right = receipt.receiptNumber,
            lineWidth = lineWidth
        )

        appendLeftRightLine(
            builder = builder,
            left = "Date:",
            right = receipt.receiptDateTime,
            lineWidth = lineWidth
        )

        appendLeftRightLine(
            builder = builder,
            left = "Cashier:",
            right = receipt.cashierName,
            lineWidth = lineWidth
        )

        appendDivider(builder, lineWidth)

        appendLeftRightLine(
            builder = builder,
            left = "ITEM",
            right = "TOTAL",
            lineWidth = lineWidth
        )

        appendBlankLine(builder)

        receipt.items.forEach { item ->
            appendReceiptItem(
                builder = builder,
                item = item,
                lineWidth = lineWidth
            )
        }

        appendDivider(builder, lineWidth)

        appendLeftRightLine(
            builder = builder,
            left = "Subtotal",
            right = "Rs ${receipt.subtotal}",
            lineWidth = lineWidth
        )

        appendLeftRightLine(
            builder = builder,
            left = "Discount",
            right = "Rs ${receipt.discount}",
            lineWidth = lineWidth
        )

        appendLeftRightLine(
            builder = builder,
            left = "Tax",
            right = "Rs ${receipt.tax}",
            lineWidth = lineWidth
        )

        appendBlankLine(builder)

        appendLeftRightLine(
            builder = builder,
            left = "TOTAL",
            right = "Rs ${receipt.total}",
            lineWidth = lineWidth
        )

        appendDivider(builder, lineWidth)

        appendCenteredLine(
            builder = builder,
            text = "PAYMENT",
            lineWidth = lineWidth
        )

        appendLeftRightLine(
            builder = builder,
            left = "Method",
            right = receipt.paymentMethod.name,
            lineWidth = lineWidth
        )

        if (receipt.amountPaid != null) {
            appendLeftRightLine(
                builder = builder,
                left = "Amount Paid",
                right = "Rs ${receipt.amountPaid}",
                lineWidth = lineWidth
            )
        }

        if (receipt.hasChange) {
            appendLeftRightLine(
                builder = builder,
                left = "Change",
                right = "Rs ${receipt.changeGiven}",
                lineWidth = lineWidth
            )
        }

        appendDivider(builder, lineWidth)

        appendCenteredLine(
            builder = builder,
            text = receipt.footerMessage.uppercase(),
            lineWidth = lineWidth
        )

        appendBlankLine(builder)
        appendBlankLine(builder)

        return builder.toString()
    }

    /**
     * Converts the formatted receipt text into ESC/POS-compatible bytes.
     *
     * Real ESC/POS printers receive bytes, not Compose UI.
     *
     * For now, we include only basic ESC/POS commands:
     * - ESC @ : Initialize printer
     * - Line feed after the receipt
     *
     * Later, we can add:
     * - Bold command
     * - Center alignment command
     * - Paper cut command
     * - QR code command
     */
    fun formatReceiptBytes(
        receipt: Receipt,
        printerConfig: PrinterConfig,
        includeCutCommand: Boolean = false
    ): ByteArray {
        val receiptText = formatReceiptText(
            receipt = receipt,
            printerConfig = printerConfig
        )

        val output = ByteArrayOutputStream()

        /**
         * ESC @
         *
         * This resets/initializes the printer before printing.
         */
        output.write(ESC_POS_INITIALIZE_PRINTER)

        /**
         * Convert receipt text into bytes.
         *
         * We use ISO-8859-1 because our current receipt uses simple Latin characters.
         * We also use "Rs" instead of the rupee symbol to avoid printer encoding issues.
         */
        output.write(
            receiptText.toByteArray(PRINTER_CHARSET)
        )

        /**
         * Feed a few blank lines after printing.
         *
         * Thermal printers usually need some extra paper feed after the receipt content.
         */
        output.write(ESC_POS_FEED_LINES)

        /**
         * Paper cut command is optional.
         *
         * Many small 58mm Bluetooth printers do not have an automatic cutter,
         * so we keep this disabled by default.
         */
        if (includeCutCommand) {
            output.write(ESC_POS_FULL_CUT)
        }

        return output.toByteArray()
    }

    /**
     * Adds one item to the receipt text.
     *
     * We print the product name and line total on the first line.
     * The quantity and unit price are printed on the next line.
     *
     * Example:
     * Latte                      Rs 120
     *   1 x Rs 120
     */
    private fun appendReceiptItem(
        builder: StringBuilder,
        item: ReceiptItem,
        lineWidth: Int
    ) {
        appendLeftRightLine(
            builder = builder,
            left = item.productName,
            right = "Rs ${item.lineTotal}",
            lineWidth = lineWidth
        )

        builder.append("  ${item.quantity} x Rs ${item.unitPrice}")
        builder.append("\n")
        builder.append("\n")
    }

    /**
     * Adds a centered line.
     *
     * Example:
     *         ROYAL COFFEE POS
     */
    private fun appendCenteredLine(
        builder: StringBuilder,
        text: String,
        lineWidth: Int
    ) {
        val cleanText = text.trim()

        if (cleanText.length >= lineWidth) {
            builder.append(cleanText.take(lineWidth))
            builder.append("\n")
            return
        }

        val leftPadding = (lineWidth - cleanText.length) / 2

        builder.append(" ".repeat(leftPadding))
        builder.append(cleanText)
        builder.append("\n")
    }

    /**
     * Adds a left/right aligned line.
     *
     * Example:
     * Subtotal                  Rs 120
     */
    private fun appendLeftRightLine(
        builder: StringBuilder,
        left: String,
        right: String,
        lineWidth: Int
    ) {
        builder.append(
            formatLeftRightLine(
                left = left,
                right = right,
                lineWidth = lineWidth
            )
        )
        builder.append("\n")
    }

    /**
     * Formats one left/right line for fixed-width printer output.
     */
    private fun formatLeftRightLine(
        left: String,
        right: String,
        lineWidth: Int
    ): String {
        val cleanLeft = left.trim()
        val cleanRight = right.trim()

        val availableLeftSpace = lineWidth - cleanRight.length

        if (availableLeftSpace <= 1) {
            return cleanRight.take(lineWidth)
        }

        val trimmedLeft = cleanLeft.take(availableLeftSpace - 1)

        return trimmedLeft.padEnd(availableLeftSpace, ' ') + cleanRight
    }

    /**
     * Adds a divider line.
     *
     * Example:
     * --------------------------------
     */
    private fun appendDivider(
        builder: StringBuilder,
        lineWidth: Int
    ) {
        builder.append("-".repeat(lineWidth))
        builder.append("\n")
    }

    /**
     * Adds a blank line.
     */
    private fun appendBlankLine(
        builder: StringBuilder
    ) {
        builder.append("\n")
    }

    companion object {
        /**
         * Character set used for basic receipt printing.
         *
         * We keep the text simple and use "Rs" instead of currency symbols
         * to avoid issues with low-cost thermal printers.
         */
        private val PRINTER_CHARSET: Charset = Charsets.ISO_8859_1

        /**
         * ESC @
         *
         * ESC/POS command to initialize/reset the printer.
         */
        private val ESC_POS_INITIALIZE_PRINTER = byteArrayOf(
            0x1B,
            0x40
        )

        /**
         * Feeds extra blank lines after receipt output.
         */
        private val ESC_POS_FEED_LINES = byteArrayOf(
            0x0A,
            0x0A,
            0x0A
        )

        /**
         * GS V 0
         *
         * ESC/POS full cut command.
         *
         * Not all small Bluetooth printers support this.
         */
        private val ESC_POS_FULL_CUT = byteArrayOf(
            0x1D,
            0x56,
            0x00
        )
    }
}